 static int scenarios,checks,failures;
 static object Call(GameManager gm,string name,params object[] args)=>typeof(GameManager).GetMethod(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).Invoke(gm,args);
 static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
 static async Task Run(string name,Func<Task> test){scenarios++;Env.Reset();try{await test().WaitAsync(TimeSpan.FromSeconds(2));Console.WriteLine("PASS "+name);}catch(Exception ex){failures++;Console.WriteLine("FAIL "+name+": "+ex.GetBaseException().Message);}}
 static Task Done(Action test){test();return Task.CompletedTask;}
 static Task Init(GameManager gm)=>(Task)Call(gm,"Init");
 static string Reward(RewardConfig r,string id)=>r.Assets.FirstOrDefault(a=>a.Id==id)?.Num;
 static async Task Main()
 {
  await Run("constructor creates real UpdateController field initializer",()=>Done(()=>{var gm=new GameManager();Check(gm.updateController!=null&&UpdateController.Constructions==1,"UpdateController initialized once");}));
  await Run("two Init waits and unawaited managers preserve native order",async()=>
  {
   var gm=new GameManager();Env.Hold("HWLeaderboardManager","MetaGameManager","CoreGameManager");int called=0;gm.RegisterOnGameManagerInitComplete(()=>{Env.Trace.Add("CompleteCallback");Check(!gm.InitComplete,"callback observes false flag");called++;});
   var task=Init(gm);Check(task!=null&&!task.IsCompleted,"real async task pending");Check(Env.Trace.Last()=="Init:MetaGameManager","first wait is meta init");Check(!Env.Trace.Contains("Init:GetNewCardPanelManager"),"meta await blocks next stage");Check(!gm.InitComplete&&called==0,"not complete before awaits");
   Env.Release("MetaGameManager");Check(Env.Trace.Last()=="Init:CoreGameManager","second wait is core init");Check(!Env.Trace.Contains("Init:SeasonManager"),"core blocks post managers");Check(!gm.InitComplete,"second wait still blocks flag");
   Env.Release("CoreGameManager");await task;Check(gm.InitComplete&&called==1,"callback then flag");Check(!Env.Held["HWLeaderboardManager"].Task.IsCompleted,"early manager task was started but not awaited");
   Check(Env.Trace.TakeLast(5).SequenceEqual(new[]{"CompleteCallback","AppOpen","Email","FixedRandom.Load","StartCoroutine"}),"callback, flag-adjacent services, coroutine order");Check(Env.Coroutines.Count==1,"real network iterator registered");
  });
  await Run("failed awaited Meta init leaves flag false",async()=>{var gm=new GameManager();Env.Hold("MetaGameManager");var task=Init(gm);Check(task!=null,"async task");var error=new ApplicationException("meta failed");Env.Held["MetaGameManager"].SetException(error);Exception actual=null;try{await task;}catch(Exception ex){actual=ex;}Check(ReferenceEquals(error,actual)&&!gm.InitComplete,"original error and false flag");Check(!Env.Trace.Contains("Init:CoreGameManager"),"no next init");});
  await Run("callback exception prevents InitComplete write",async()=>{var gm=new GameManager();var error=new ApplicationException("callback failed");gm.RegisterOnGameManagerInitComplete(()=>throw error);var task=Init(gm);Check(task!=null,"async task");Exception actual=null;try{await task;}catch(Exception ex){actual=ex;}Check(ReferenceEquals(actual,error)&&!gm.InitComplete,"callback failure before flag");Check(!Env.Trace.Contains("AppOpen"),"no service calls after callback failure");});
  await Run("post-flag service failure keeps original true flag",async()=>{var gm=new GameManager();ReportEventsManager.Instance.ThrowAppOpen=true;var task=Init(gm);Check(task!=null,"async task");bool failed=false;try{await task;}catch(ApplicationException){failed=true;}Check(failed&&gm.InitComplete,"flag already true before AppOpen exception");Check(!Env.Trace.Contains("Email"),"later steps stop");});
  await Run("completion registration before and after flag",async()=>{var gm=new GameManager();string order="";gm.RegisterOnGameManagerInitComplete(()=>order+="a");gm.RegisterOnGameManagerInitComplete(()=>order+="b");gm.RegisterOnGameManagerInitComplete(null);await Init(gm);Check(order=="ab","Combine order retained");gm.RegisterOnGameManagerInitComplete(()=>order+="c");Check(order=="abc","completed registration invoked immediately");});
  await Run("existing PlayerPrefs and returning-user panels preserve branches",async()=>{var gm=new GameManager();DbtSaveDataManager_PlayerGuideData.I.Data.isFirstThroghGame=false;UnityEngine.PlayerPrefs.Values["VibratorEnable"]=1;SDKModule.ABTestManager.Instance.WeeklyClashImprove02IsBTest=true;await Init(gm);Check(UnityEngine.PlayerPrefs.Values["VibratorEnable"]==1,"existing preference untouched");Check(Env.Trace.Contains("MetaPanel:2")&&Env.Trace.Contains("Event:InitGameEndCheckIsHasLegacyBox"),"returning user enters meta and legacy check");Check(Env.Trace.Contains("Active:Base/ATestPostProcess:False")&&Env.Trace.Contains("Active:Base/BTestPostProcess:True"),"AB postprocess exact toggles");});
  await Run("fresh user no return-home prefetch and DanChange after listener",async()=>{var gm=new GameManager();await Init(gm);Check(!Env.Trace.Any(t=>t.Contains("ClimbRankPanel")),"first entry does not prefetch climb");Check(Env.Trace.IndexOf("Listen:DanChange")<Env.Trace.IndexOf("Event:DanChange"),"listener before initial event");Check(Env.Trace.Contains("RankUpdate"),"original initial rank callback runs");});
  await Run("timer migration fixes old dates and retains original save order",async()=>{var shop=DbtSaveDataManager_PlayerShopData.I.Data;shop.timingPushGiftPackageCdIng=true;shop.isShowNewBieGiftPack=true;shop.canTimingPushGiftPackage=true;TimeManager.Instance.Timers["NewBieGiftPackKey"]=new("NewBieGiftPackKey"){StartTime=new(2024,12,31)};TimeManager.Instance.Timers["GiftPackagePushCountdownKey"]=new("GiftPackagePushCountdownKey"){TargetEndTime=new(2024,12,31)};await Init(new());Check(!shop.timingPushGiftPackageCdIng&&shop.hadHandleTwoSixOneBug,"original migration flags");Check(Env.Trace.Contains("Restart:NewBieGiftPackKey:2:True")&&Env.Trace.Contains("Restart:GiftPackagePushCountdownKey:2:True"),"old timer restart lengths");Check(Env.Trace.Count(t=>t=="Save:Shop")==2&&Env.Trace.Count(t=>t=="Save:Time")==1,"save cd reset then migration shop/time");});
  await Run("timer migration alternate four-day branch and skip fixed data",async()=>{TimeManager.Instance.Timers["CanGiftPackagePushKey"]=new("CanGiftPackagePushKey"){StartTime=new(2024,1,1)};await Init(new());Check(Env.Trace.Contains("Restart:CanGiftPackagePushKey:4:True"),"four day cooldown");Env.Trace.Clear();await Init(new());Check(!Env.Trace.Any(t=>t.StartsWith("Restart:")),"migration already handled");});
  await Run("selectable offer first-time creates four-day timer",async()=>{SDKModule.ABTestManager.Instance.SelectableOfferIsOn=true;await Init(new());Check(Env.Trace.Contains("CreateTimer:CanGiftPackagePushKey:4:True:False"),"native first timer arguments");});
  await Run("selectable offer return without newbie directly permits push",async()=>{DbtSaveDataManager_PlayerGuideData.I.Data.isFirstThroghGame=false;SDKModule.ABTestManager.Instance.SelectableOfferIsOn=true;await Init(new());Check(DbtSaveDataManager_PlayerShopData.I.Data.canTimingPushGiftPackage,"original permission change");Check(Env.Trace.Contains("GetTimer:GiftPackagePushOffsetKey"),"original offset timer lookup retained");});
  await Run("selectable offer return with newbie uses four minus remaining",async()=>{DbtSaveDataManager_PlayerGuideData.I.Data.isFirstThroghGame=false;DbtSaveDataManager_PlayerShopData.I.Data.isShowNewBieGiftPack=true;SDKModule.ABTestManager.Instance.SelectableOfferIsOn=true;TimeManager.Instance.Timers["NewBieGiftPackKey"]=new("NewBieGiftPackKey"){Remaining=TimeSpan.FromDays(1.5)};await Init(new());Check(Env.Trace.Contains("CreateTimer:CanGiftPackagePushKey:2.5:True:False"),"remaining duration subtraction");});
  await Run("daily and weekly registrations preserve data resets and events",()=>Done(()=>{var gm=new GameManager();DailyBlessManager.Instance.Test=true;Call(gm,"RegisterOnTimeToZero");Call(gm,"RegisterOnTimeToMonDayZero");Check(TimeManager.Instance.Daily.Count==9&&TimeManager.Instance.Weekly.Count==3,"native callback count");DbtSaveDataManager_PlayerCoreData.I.Data.nowLingquReward=true;DbtSaveDataManager_PlayerShopData.I.Data.cardPackBuyCountNowWeek["x"]=8;DbtSaveDataManager_PlayerShopData.I.Data.playerRuneStoneBuyState["r"]=true;foreach(var action in TimeManager.Instance.Daily)action();foreach(var action in TimeManager.Instance.Weekly)action();Check(!DbtSaveDataManager_PlayerCoreData.I.Data.nowLingquReward,"daily reward flag reset");Check(DbtSaveDataManager_PlayerShopData.I.Data.cardPackBuyCountNowWeek["x"]==0&&!DbtSaveDataManager_PlayerShopData.I.Data.playerRuneStoneBuyState["r"],"snapshot keys reset values");Check(Env.Trace.Contains("Event:TimeToZeroRefreshSubscription")&&Env.Trace.Contains("Event:RefreshRuneStonePack"),"original reset events");Check(Env.Trace.Take(3).All(t=>t=="RegisterDaily"),"three shop actions registered first");}));
  await Run("network iterator delays, yields UI tasks and pauses/resumes",()=>Done(()=>{var gm=new GameManager(){InitComplete=true};QuickTutor.TutorialManager.Instance.Complete.Add("1008");TimeManager.Instance.IsNetworkConnected=false;CoreGameManager.Gaming=true;var e=(IEnumerator)Call(gm,"CheckNetworkState");Check(e!=null&&e.MoveNext()&&e.Current is UnityEngine.WaitForSeconds w&&Math.Abs(w.Value-.02f)<1e-5,"first yield exactly .02 seconds");Check(e.MoveNext()&&e.Current is Task,"offline yields real ShowPanel result");Check(!Env.Trace.Contains("BattlePause:True"),"pause after UI yield resumes");Check(e.MoveNext()&&e.Current is UnityEngine.WaitForSeconds,"loop returns to delay");Check(Env.Trace.Contains("BattlePause:True")&&Env.Trace.Contains("AIPause:True"),"original two managers paused");TimeManager.Instance.IsNetworkConnected=true;Check(e.MoveNext()&&e.Current is Task,"online yields HidePanel");Check(e.MoveNext()&&Env.Trace.Contains("BattlePause:False")&&Env.Trace.Contains("AIPause:False"),"resume after hide yield");}));
  await Run("network iterator retains tutorial and MaskPanel gates",()=>Done(()=>{var gm=new GameManager(){InitComplete=true};TimeManager.Instance.IsNetworkConnected=false;var e=(IEnumerator)Call(gm,"CheckNetworkState");Check(e!=null&&e.MoveNext()&&e.MoveNext(),"incomplete tutorial returns another delay");Check(!Env.Trace.Any(t=>t.StartsWith("ShowPanel:")),"tutorial blocks offline UI");QuickTutor.TutorialManager.Instance.Complete.Add("1008");UIFramework.UIManager.Instance.Mask=true;Check(!e.MoveNext(),"native MaskPanel branch ends iterator");}));
  foreach(var pair in new[]{(GameType.PVP,2,true),(GameType.PVE,3,false),(GameType.SeasonPVP,2,false),(GameType.SubGamePVP,2,true)}){var p=pair;await Run("EnterMeta original mode "+p.Item1,()=>Done(()=>{var gm=new GameManager();BattleGameManager.Instance.GameType=p.Item1;var result=new BattleResult();Call(gm,"EnterMeta",result);Check(Env.Trace.Contains("MetaPanel:"+p.Item2),"native mode panel");Check(Env.Trace.Contains("PanelPop")==p.Item3,"native popup branch");if(p.Item1==GameType.SubGamePVP)Check(ReferenceEquals(SubGameChaosTrailsManager.Instance.Last,result),"original BattleResult cast forwarded");}));}
  await Run("LoadEnd first game triggers core event after original listener",async()=>{var gm=new GameManager();await Init(gm);Call(gm,"LoadEnd",new object[]{null});Check(CoreGameManager.Context!=null&&CoreGameManager.Context.Show&&CoreGameManager.Context.GameType==GameType.PVP,"original core context created");Check(CoreGameManager.Context.Callback!=null,"original deferred reward callback retained");});
  await Run("training reward and guided completion preserve isolated path",()=>Done(()=>{var gm=new GameManager();Call(gm,"StartCoreGame",new object[]{null});TrainingGroundManager.IsInTrainingGround=true;TrainingGroundManager.IsInGuidedGame=true;var r=CoreGameManager.Context.Callback(false);Check(Reward(r,"20007")=="5"&&r.Assets.Count==1,"training lose exp only");Check(Env.Trace.Contains("TrainingComplete:False")&&!Env.Trace.Any(t=>t.StartsWith("GameFinish:")),"guided completion without standard report path");}));
  await Run("standard win original assets, trophy and report",()=>Done(()=>{Call(new GameManager(),"StartCoreGame",new object[]{null});var r=CoreGameManager.Context.Callback(true);Check(r.Assets.Select(a=>a.Id).SequenceEqual(new[]{"20005","20006","20007","20004"}),"native reward order");Check(Reward(r,"20005")=="10"&&Reward(r,"20004")=="9","original config and computed trophy");Check(ReferenceEquals(BattleGameManager.Instance.rewardConfig,r)&&ReferenceEquals(BattleGameManager.Instance.tempConfig,r),"same reward object on both fields");Check(Env.Trace.Contains("ChangeTrophy:1001:9:False")&&Env.Trace.Contains("GameFinish:True:0:PVP"),"original side effects");}));
  await Run("NoBet and monthly win retains prebonus accounting",()=>Done(()=>{Call(new GameManager(),"StartCoreGame",new object[]{null});SDKModule.ABTestManager.Instance.NoBetIsBTest=true;MonthlyPassManager.Instance.Bought=true;var r=CoreGameManager.Context.Callback(true);Check(Reward(r,"20005")=="60","float32 twenty percent month bonus");Check(Env.Trace.Contains("NoBetGold:50"),"no-bet accounting uses before bonus");}));
  await Run("new arena excess trophy removal and season exp",()=>Done(()=>{Call(new GameManager(),"StartCoreGame",new object[]{null});SDKModule.ABTestManager.Instance.NewArenaProcessIsBTest=true;SDKModule.ABTestManager.Instance.SeasonIsBTest=true;SeasonManager.Instance.Exp=3;ArenaManager.Instance.Trophies=98;var r=CoreGameManager.Context.Callback(true);Check(Env.Trace.Contains("Lose:20004:7:False:none"),"original excess removal");Check(Reward(r,"20017")=="3","season positive reward");}));
  await Run("collected arena suppresses trophy reward and mutation",()=>Done(()=>{Call(new GameManager(),"StartCoreGame",new object[]{null});ArenaManager.Instance.Collected=true;var r=CoreGameManager.Context.Callback(true);Check(Reward(r,"20004")==null&&!Env.Trace.Any(t=>t.StartsWith("ChangeTrophy:")),"collected arena gate");}));
  await Run("loss minimum playtime gate and original clamped-display side effect",()=>Done(()=>{Call(new GameManager(),"StartCoreGame",new object[]{null});SDKModule.ABTestManager.Instance.NewArenaProcessIsBTest=true;ArenaManager.Instance.Trophies=2;BattleGameManager.Instance.ElapseTime=10;var shortR=CoreGameManager.Context.Callback(false);Check(Reward(shortR,"20004")==null,"ten second loss excludes trophy");BattleGameManager.Instance.ElapseTime=10.01f;var r=CoreGameManager.Context.Callback(false);Check(Reward(r,"20004")=="-2","reward clamps display loss to available trophy");Check(Env.Trace.Contains("ChangeTrophy:1001:-7:False"),"original ChangeArenaTrophy still uses full configured punish");}));
  await Run("monthly float conversion preserves native int saturation",()=>Done(()=>{Call(new GameManager(),"StartCoreGame",new object[]{null});MonthlyPassManager.Instance.Bought=true;SDKModule.ABTestManager.Instance.NoBetIsBTest=true;BattleGameManager.Instance.BetRewardNum=int.MaxValue.ToString();Check(Reward(CoreGameManager.Context.Callback(true),"20005")==int.MaxValue.ToString(),"FCVTZS saturates positive overflow");BattleGameManager.Instance.BetRewardNum=int.MinValue.ToString();Check(Reward(CoreGameManager.Context.Callback(true),"20005")==int.MinValue.ToString(),"FCVTZS saturates negative overflow");}));
  await Run("monthly bonus actual reward callback matches original ARM64 oracle",()=>Done(()=>{Call(new GameManager(),"StartCoreGame",new object[]{null});MonthlyPassManager.Instance.Bought=true;SDKModule.ABTestManager.Instance.NoBetIsBTest=true;using var doc=JsonDocument.Parse(File.ReadAllText("work/gamemanager-recovery/month-bonus-native-golden.json"));foreach(var row in doc.RootElement.GetProperty("cases").EnumerateArray()){int input=row.GetProperty("input").GetInt32();BattleGameManager.Instance.BetRewardNum=input.ToString();Check(Reward(CoreGameManager.Context.Callback(true),"20005")==row.GetProperty("expected").GetInt32().ToString(),"native SCVTF/FMUL/FCVTZS input="+input);}}));
  await Run("Update and CloseLoadPanel preserve own flags and call gates",async()=>{var gm=new GameManager();Call(gm,"Update");Check(!Env.Trace.Any(t=>t.StartsWith("Update:")),"update waits own InitComplete");await Init(gm);Call(gm,"Update");Check(Env.Trace.Contains("Update:0.02"),"update passes deltaTime");Call(gm,"CloseLoadPanel",new object[]{null});Check(Env.Trace.Contains("Interactive:")&&Env.Trace.Contains("CheckStartupGift")&&!Env.Trace.Contains("FirstPopPacks"),"first game interactive empty payload and gift check");});
  Console.WriteLine($"RESULT scenarios={scenarios} checks={checks} failures={failures}");Environment.ExitCode=failures==0?0:1;
 }
